descriptor.templateCss:
/* ═══════════════════════════════════════════════════════════════
   SUNKUU 360 — Template 3EM  |  TB 4.3.0PE  |  v3
   Tokens: --navy #00008C · --teal #00EBC8 · --bg #EBF0F7
   v3: legibilidad mejorada, emojis→Material Icons, badges
       normalizados, uppercase auditado, fallbacks eliminados
   ═══════════════════════════════════════════════════════════════ */

#s3em-root {
  --navy: #00008C;
  --teal: #00EBC8;
  --bg:   #EBF0F7;
  --surf: #FFFFFF;
  --pri:  #0D1B2E;
  --sec:  #5A6E8A;
  --ter:  #96AABF;
  --brd:  #D4E0EE;
  --pos:  #10B981;
  --neg:  #EF4444;
  --warn: #F59E0B;
  --ind:  #6366F1;
  --shd:  0 1px 3px rgba(13,27,46,.06), 0 8px 28px rgba(13,27,46,.08);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

#s3em-root {
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  background: var(--bg);
  min-height: 100%;
  display: flex;
  flex-direction: column;
}

/* ── HEADER ─────────────────────────────────────────────────────── */
#s3em-hdr {
  background-color: var(--navy);
  box-shadow: 0 2px 14px rgba(0,0,0,.32);
  position: sticky;
  top: 0;
  z-index: 30;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
}

.hdr-left  { display: flex; align-items: center; gap: 12px; }
.hdr-right { display: flex; align-items: center; gap: 14px; }
.hdr-div   { width: 1px; height: 22px; background: rgba(255,255,255,.1); }

.hdr-logo  { display: flex; align-items: center; gap: 7px; }
.brand-img{height:22px;width:auto;display:block}
.logo-sub  { font-weight: 400; font-size: 9px; color: rgba(255,255,255,.8); margin-left: 4px; letter-spacing: .05em; }

.hdr-inst-badge {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 8px;
  padding: 5px 12px;
  display: flex; align-items: center; gap: 7px;
  cursor: pointer;
}
.inst-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--pos); box-shadow: 0 0 4px rgba(16,185,129,.8); }
.hdr-inst-badge span:not(.inst-chevron) { font-size: 13px; font-weight: 700; color: white; }
.inst-chevron { font-size: 9px; color: rgba(255,255,255,.4); }

#btn-fleet {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 8px;
  padding: 6px 11px;
  cursor: pointer;
  color: rgba(255,255,255,.8);
  font-size: 12px;
  font-weight: 600;
}
#btn-fleet:hover { background: rgba(255,255,255,.15); color: white; }

.hdr-status { display: flex; align-items: center; gap: 5px; }
.status-dot  { width: 7px; height: 7px; border-radius: 50%; background: var(--pos); box-shadow: 0 0 6px rgba(16,185,129,.8); }
.status-text { font-size: 12px; color: rgba(255,255,255,.75); }

/* ── ANCHOR NAV ──────────────────────────────────────────────────── */
#s3em-nav {
  background-color: var(--navy);
  border-top: 1px solid rgba(255,255,255,.07);
  position: sticky;
  top: 56px;
  z-index: 29;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  box-shadow: 0 2px 8px rgba(0,0,140,.25);
}

.nav-inner { display: flex; height: 100%; }

.anc {
  padding: 0 15px;
  height: 100%;
  border: none;
  cursor: pointer;
  font-size: 12px;
  font-weight: 600;
  background: transparent;
  color: rgba(255,255,255,.55);
  border-bottom: 2.5px solid transparent;
  transition: all .15s;
}
.anc:hover  { color: rgba(255,255,255,.85); }
.anc.active { color: white; border-bottom-color: var(--teal); }

.nav-live {
  display: flex; align-items: center; gap: 6px;
  background: rgba(0,235,200,.1);
  border: 1px solid rgba(0,235,200,.2);
  border-radius: 7px;
  padding: 4px 11px;
}
.nav-live span { font-size: 11px; font-weight: 600; color: var(--teal); }
.live-pulse {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--teal);
  box-shadow: 0 0 5px rgba(0,235,200,.8);
  animation: pulse 2s infinite;
}
@keyframes pulse { 0%,100%{opacity:1} 50%{opacity:.4} }

/* ── CONTENT ─────────────────────────────────────────────────────── */
#s3em-content {
  max-width: 1440px;
  margin: 0 auto;
  padding: 4px 24px 60px;
  width: 100%;
}

/* ── SECTION HEADER ──────────────────────────────────────────────── */
.s3em-section { margin-bottom: 4px; }

.sec-hdr {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  margin: 28px 0 16px;
}
.sec-num {
  width: 34px; height: 34px; border-radius: 9px; flex-shrink: 0;
  background: linear-gradient(135deg, var(--navy), #0a0abb);
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 2px 10px rgba(0,0,140,.3);
  font-size: 12px; font-weight: 800; color: var(--teal);
}
.sec-title { font-size: 17px; font-weight: 800; color: var(--navy); letter-spacing: -.02em; line-height: 1; }
.sec-sub   { font-size: 12px; color: var(--sec); margin-top: 5px; }
.sec-line  { align-self: center; flex: 1; max-width: 180px; height: 1px; background: var(--brd); }

/* ── KPI CARDS ───────────────────────────────────────────────────── */
.kpi-grid { display: grid; grid-template-columns: repeat(4,1fr); gap: 14px; }

.kpi-card {
  background: var(--surf);
  border-radius: 16px;
  box-shadow: var(--shd);
  border: 1px solid var(--brd);
  border-top: 3px solid var(--teal);
  padding: 18px 20px 14px;
  display: flex; flex-direction: column; gap: 8px;
}
.kpi-pos  { border-top-color: var(--pos) !important; }
.kpi-navy { border-top-color: var(--navy) !important; }

.kc-top { display: flex; justify-content: space-between; align-items: center; }

/* Label KPI: texto puro descriptivo — uppercase ok, sin unidades */
.kc-label {
  font-size: 10px; font-weight: 700;
  letter-spacing: .07em; text-transform: uppercase;
  color: var(--sec);    /* subido de --sec era ya correcto, antes era más claro */
  line-height: 1.4;
}

/* Ícono Material Icon — reemplaza emoji */
.kc-icon {
  font-family: 'Material Icons';
  font-size: 20px;
  color: var(--ter);
  font-style: normal;
  font-weight: normal;
  line-height: 1;
  user-select: none;
}

.kc-val-row { display: flex; align-items: baseline; gap: 5px; }
.kc-val  { font-size: 36px; font-weight: 800; color: var(--pri); letter-spacing: -.04em; line-height: 1; font-variant-numeric: tabular-nums; }
.kc-unit { font-size: 14px; font-weight: 700; color: var(--navy); }

/* Chip de estado — normalizado contra Portal de Flota */
.kc-chip {
  font-size: 10px; font-weight: 700;
  padding: 4px 10px; border-radius: 20px;
  align-self: flex-start;
  background: rgba(90,110,138,.1);
  color: var(--sec);
  border: 1px solid rgba(90,110,138,.2);
}
.kc-chip.ok    { background: rgba(16,185,129,.1);  color: #065F46; border-color: rgba(16,185,129,.22); }
.kc-chip.warn  { background: rgba(245,158,11,.1);  color: #92400E; border-color: rgba(245,158,11,.22); }
.kc-chip.alert { background: rgba(239,68,68,.1);   color: #991B1B; border-color: rgba(239,68,68,.22); }

/* ── COMPARISON CARDS ────────────────────────────────────────────── */
.cmp-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 14px; margin-top: 14px; }

.cmp-card {
  background: var(--surf);
  border-radius: 12px;
  box-shadow: var(--shd);
  border: 1px solid var(--brd);
  padding: 14px 18px;
  display: flex; gap: 14px; align-items: center;
}
.cmp-icon {
  width: 42px; height: 42px; border-radius: 10px; flex-shrink: 0;
  background: rgba(0,0,140,.08); border: 1px solid rgba(0,0,140,.15);
  display: flex; align-items: center; justify-content: center;
  font-family: 'Material Icons'; font-size: 20px;
  color: var(--navy); font-style: normal; font-weight: normal;
  line-height: 1; user-select: none;
}
.cmp-label { font-size: 11px; color: var(--sec); margin-bottom: 3px; }
.cmp-val   { font-size: 18px; font-weight: 800; color: var(--pri); font-variant-numeric: tabular-nums; }
.cmp-sub   { font-size: 11px; color: var(--sec); margin-top: 2px; }

/* ── INTELLIGENCE CARD ───────────────────────────────────────────── */
#intel-card {
  margin-top: 14px;
  background: linear-gradient(135deg, var(--navy) 0%, #0a0aaa 50%, #000f72 100%);
  border-radius: 18px;
  padding: 22px 26px;
  border: 1px solid rgba(0,235,200,.22);
  box-shadow: 0 6px 32px rgba(0,0,140,.30);
}
.ic-top {
  display: flex; align-items: center; gap: 10px;
  justify-content: space-between;
  margin-bottom: 16px; flex-wrap: wrap;
  text-align: left;
}
.ic-icon-wrap {
  width: 40px; height: 40px; border-radius: 10px; flex-shrink: 0;
  background: rgba(0,235,200,.14); border: 1px solid rgba(0,235,200,.28);
  display: flex; align-items: center; justify-content: center;
}
/* Ícono robot → Material Icon smart_toy */
.ic-icon {
  font-family: 'Material Icons';
  font-size: 20px; color: var(--teal);
  font-style: normal; font-weight: normal;
  line-height: 1; user-select: none;
}
.ic-badge { font-size: 10px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; color: var(--teal); }
.ic-date  { font-size: 10px; color: rgba(255,255,255,.45); margin-top: 2px; }
.ic-tag {
  background: rgba(0,235,200,.12); border: 1px solid rgba(0,235,200,.22);
  border-radius: 8px; padding: 5px 12px;
  font-size: 10px; font-weight: 700; color: rgba(0,235,200,.9);
  flex-shrink: 0;
}
.ic-text {
  font-size: 15px; font-weight: 400; line-height: 1.7;
  color: rgba(255,255,255,.92); margin: 0 0 20px;
}
.ic-metrics { display: grid; grid-template-columns: repeat(3,1fr); gap: 10px; }
.ic-metric {
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 12px; padding: 12px 16px;
}
/* Labels dentro de intel card: sobre fondo oscuro, sin uppercase con unidades */
.icm-label { font-size: 10px; color: rgba(255,255,255,.55); letter-spacing: .05em; margin-bottom: 6px; }
.icm-val   { font-size: 20px; font-weight: 800; color: white; line-height: 1; font-variant-numeric: tabular-nums; }
.icm-sub   { font-size: 11px; color: rgba(255,255,255,.5); margin-top: 5px; }

/* ── CHART CARDS ─────────────────────────────────────────────────── */
.chart-card {
  background: var(--surf);
  border-radius: 16px;
  box-shadow: var(--shd);
  border: 1px solid var(--brd);
  padding: 20px;
}
.chart-wrap-tall  { position: relative; height: 240px; }
.chart-wrap-med   { position: relative; height: 200px; }
.chart-wrap-fp    { position: relative; height: 145px; }
.chart-wrap-donut { position: relative; width: 90px; height: 90px; flex-shrink: 0; }

.chart-ctrl-row {
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: 16px; flex-wrap: wrap; gap: 10px;
}
/* Label de gráfico: texto descriptivo puro, sin unidades → uppercase ok */
.chart-label-sm { font-size: 11px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--sec); }

.t-btns { display: flex; gap: 2px; background: #F0F6FC; border-radius: 9px; padding: 3px; }
.tbtn {
  padding: 5px 14px; border-radius: 6px; border: none; cursor: pointer;
  font-size: 11px; font-weight: 600; background: transparent; color: var(--sec);
  transition: all .15s;
}
.tbtn.active             { background: var(--navy); color: white; }
.tbtn:hover:not(.active) { background: rgba(0,0,140,.07); }

.chart-legend { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
.leg     { display: flex; align-items: center; gap: 4px; font-size: 11px; color: var(--sec); }
.leg-dot { width: 14px; height: 2.5px; border-radius: 1px; }

/* ── DEMAND BOTTOM ───────────────────────────────────────────────── */
.dem-bottom { display: grid; grid-template-columns: 3fr 1.6fr; gap: 12px; margin-top: 16px; }
.dem-stats  { display: grid; grid-template-columns: repeat(3,1fr); gap: 10px; }
.dem-stat {
  background: #F4F8FC; border-radius: 10px; padding: 12px 14px;
  border-left: 3px solid var(--navy);
}
.ds-lbl { font-size: 11px; color: var(--sec); margin-bottom: 2px; }
.ds-val { font-size: 17px; font-weight: 800; color: var(--pri); font-variant-numeric: tabular-nums; }
.ds-sub { font-size: 11px; color: var(--sec); margin-top: 1px; }
.ds-neg { color: var(--neg); }
.ds-pos { color: var(--pos); }

.donut-block {
  background: #F4F8FC; border-radius: 10px; padding: 12px 14px;
  display: flex; align-items: center; gap: 12px;
}
#dist-legend { flex: 1; }
.dist-leg-title { font-size: 11px; font-weight: 700; color: var(--sec); letter-spacing: .05em; margin-bottom: 8px; }
.dl-row  { display: flex; align-items: center; gap: 6px; margin-bottom: 5px; }
.dl-dot  { width: 7px; height: 7px; border-radius: 50%; flex-shrink: 0; }
.dl-name { font-size: 11px; color: var(--sec); flex: 1; }
.dl-pct  { font-size: 12px; font-weight: 800; color: var(--pri); font-variant-numeric: tabular-nums; }

/* ── PHASE TABLE ─────────────────────────────────────────────────── */
.table-wrap {
  background: var(--surf);
  border-radius: 16px;
  box-shadow: var(--shd);
  border: 1px solid var(--brd);
  overflow: hidden;
}
.phase-tbl { width: 100%; border-collapse: collapse; }
.phase-tbl thead tr { background: #F0F6FC; }
.phase-tbl th {
  padding: 12px 18px; text-align: right;
  font-size: 11px; font-weight: 700; color: var(--sec);
  letter-spacing: .05em; text-transform: uppercase;
}
.phase-tbl th:first-child { text-align: left; }
.phase-tbl td { padding: 12px 18px; text-align: right; border-top: 1px solid var(--brd); }
.phase-tbl td:first-child { text-align: left; }
.phase-tbl tr:nth-child(even) td { background: rgba(240,246,252,.6); }
.pt-var  { font-size: 13px; font-weight: 600; color: var(--pri); }
.pt-unit { font-size: 11px; color: var(--sec); margin-top: 1px; }
.pt-val  { font-size: 15px; font-weight: 700; color: var(--pri); font-variant-numeric: tabular-nums; }
.pt-range{ font-size: 10px; color: var(--sec); margin-top: 2px; }
.ph-dot  { display: inline-block; width: 9px; height: 9px; border-radius: 50%; margin-right: 6px; vertical-align: middle; }
.loading-row { color: var(--sec); font-size: 13px; text-align: center; padding: 20px !important; }

/* ── ANALYTICS ───────────────────────────────────────────────────── */
.anal-grid { display: grid; grid-template-columns: 3fr 2fr; gap: 14px; }

.stats-card {
  background: var(--surf); border-radius: 16px;
  box-shadow: var(--shd); border: 1px solid var(--brd); overflow: hidden;
}
.sc-hdr {
  padding: 13px 18px; border-bottom: 1px solid var(--brd);
  display: flex; align-items: center; gap: 8px;
}
.sc-accent { width: 3px; height: 18px; border-radius: 2px; background: var(--teal); }
.sc-title  { font-size: 12px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--sec); }

.stats-tbl { width: 100%; border-collapse: collapse; }
.stats-tbl th {
  padding: 9px 12px; text-align: right;
  font-size: 10px; font-weight: 700; color: var(--sec);
  letter-spacing: .05em; text-transform: uppercase; background: #F4F8FC;
}
.stats-tbl th:first-child { text-align: left; }
.stats-tbl td { padding: 11px 12px; text-align: right; border-top: 1px solid var(--brd); }
.stats-tbl td:first-child { text-align: left; }
.stats-tbl tr:nth-child(even) td { background: rgba(244,248,252,.65); }
.stt-name { font-size: 13px; font-weight: 600; }
.stt-dot  { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 6px; }
.stt-val  { font-size: 13px; font-weight: 700; color: var(--pri); font-variant-numeric: tabular-nums; }

/* ── COST CARD ────────────────────────────────────────────────────── */
#cost-card {
  background: linear-gradient(135deg, var(--navy) 0%, #0000BB 100%);
  border-radius: 16px;
  padding: 20px;
  display: flex; flex-direction: column; gap: 11px;
}
.cc-head   { font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: rgba(255,255,255,.65); }
.cc-tarifa { font-size: 11px; color: rgba(255,255,255,.55); }
.cc-row {
  display: flex; justify-content: space-between;
  border-bottom: 1px solid rgba(255,255,255,.11); padding-bottom: 9px;
  font-size: 12px;
}
.cc-row span:first-child { color: rgba(255,255,255,.7); }
.cc-row span:last-child  { font-size: 14px; font-weight: 700; color: white; font-variant-numeric: tabular-nums; }
.cc-costo span:last-child { color: var(--teal); }
.cc-proj-box {
  background: rgba(0,235,200,.1);
  border: 1px solid rgba(0,235,200,.25);
  border-radius: 10px; padding: 12px;
}
.cc-proj-lbl { font-size: 11px; color: var(--teal); margin-bottom: 5px; }
.cc-proj-kwh { font-size: 22px; font-weight: 800; color: white; line-height: 1; font-variant-numeric: tabular-nums; }
.cc-proj-sol { font-size: 14px; font-weight: 700; color: var(--teal); margin-top: 4px; }
.cc-bars-wrap {
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 8px; padding: 10px 12px;
}
.cc-bars-lbl { font-size: 10px; color: rgba(255,255,255,.5); letter-spacing: .05em; margin-bottom: 6px; }

/* ── QUALITY / FP CARDS ───────────────────────────────────────────── */
.fp-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 14px; }

.fp-card {
  background: var(--surf); border-radius: 16px;
  box-shadow: var(--shd); border: 1px solid var(--brd);
  padding: 18px 20px;
}
.fp-top    { display: flex; justify-content: space-between; margin-bottom: 12px; }
.fp-ph     { display: flex; align-items: center; gap: 6px; }
.fp-ph-dot { width: 9px; height: 9px; border-radius: 50%; }
.fp-ph-name{ font-size: 12px; font-weight: 700; color: var(--sec); text-transform: uppercase; letter-spacing: .07em; }
.fp-badge  {
  font-size: 10px; font-weight: 700; padding: 4px 10px; border-radius: 20px;
  background: rgba(16,185,129,.12); color: var(--pos);
  border: 1px solid rgba(16,185,129,.22);
}
.fp-badge.warn { background: rgba(245,158,11,.12); color: var(--warn); border-color: rgba(245,158,11,.22); }
.fp-voltage { font-size: 28px; font-weight: 800; color: var(--pri); font-variant-numeric: tabular-nums; margin-bottom: 12px; }
.fp-fp-row  { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
.fp-fp-lbl  { font-size: 12px; color: var(--sec); }
.fp-fp-val  { font-size: 20px; font-weight: 800; font-variant-numeric: tabular-nums; }
.fp-bar-track { height: 6px; background: var(--brd); border-radius: 3px; overflow: hidden; }
.fp-bar-fill  { height: 100%; border-radius: 3px; transition: width .4s; }

/* ── ALARMS ──────────────────────────────────────────────────────── */
.al-hdr {
  padding: 13px 18px; background: var(--surf);
  border: 1px solid var(--brd); border-radius: 16px 16px 0 0;
  display: flex; align-items: center; gap: 8px;
}
.al-accent { width: 3px; height: 18px; border-radius: 2px; background: var(--warn); }
.al-title  { font-size: 12px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--sec); flex: 1; }
.al-badge-ok {
  font-size: 10px; font-weight: 700; color: var(--pos);
  background: #ECFDF5; padding: 4px 10px; border-radius: 20px;
  border: 1px solid rgba(16,185,129,.22);
}
#alarm-list { background: var(--surf); border: 1px solid var(--brd); border-top: none; border-radius: 0 0 16px 16px; }
.al-row {
  padding: 12px 18px; border-top: 1px solid var(--brd);
  display: flex; gap: 12px; align-items: center;
}
.al-dot   { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }
.al-info  { flex: 1; min-width: 0; }
.al-tipo  { font-size: 13px; font-weight: 600; color: var(--pri); }
.al-fase  { font-size: 11px; color: var(--sec); margin-left: 8px; }
.al-fecha { font-size: 11px; color: var(--sec); white-space: nowrap; }
.al-dur   { font-size: 11px; color: var(--sec); white-space: nowrap; }
.al-res   {
  font-size: 10px; font-weight: 700; color: var(--pos);
  background: #ECFDF5; padding: 3px 9px; border-radius: 20px;
  border: 1px solid rgba(16,185,129,.22); flex-shrink: 0;
}

/* ── CONFIG PANEL ────────────────────────────────────────────────── */
#cfg-panel { margin-top: 20px; background: var(--surf); border-radius: 16px; border: 1px solid var(--brd); overflow: hidden; }
#cfg-toggle {
  width: 100%; padding: 14px 20px; border: none; cursor: pointer;
  background: transparent;
  display: flex; align-items: center; gap: 10px;
  font-size: 13px; font-weight: 700; color: var(--navy);
}
#cfg-toggle:hover { background: rgba(0,0,140,.03); }
.cfg-badge { font-size: 10px; color: var(--pos); background: #ECFDF5; padding: 3px 9px; border-radius: 20px; border: 1px solid rgba(16,185,129,.22); }
#cfg-arrow { font-size: 12px; color: var(--ter); margin-left: auto; transition: transform .2s; }
#cfg-body  { border-top: 1px solid var(--brd); padding: 16px 20px; }
.cfg-grid  { display: grid; grid-template-columns: repeat(3,1fr); gap: 10px; margin-bottom: 12px; }
.cfg-item  { background: #F4F8FC; border-radius: 10px; padding: 10px 14px; }
.cfg-key   { font-size: 10px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--sec); margin-bottom: 4px; }
.cfg-val   { font-size: 14px; font-weight: 700; color: var(--pri); }
.cfg-note  { font-size: 11px; color: var(--sec); padding: 10px 14px; background: rgba(0,0,140,.04); border-radius: 10px; border: 1px dashed rgba(0,0,140,.2); line-height: 1.5; }

/* ── ACTION BUTTONS ──────────────────────────────────────────────── */
.act-row { display: grid; grid-template-columns: repeat(3,1fr); gap: 12px; margin-top: 20px; }
.act-btn {
  background: transparent; border-radius: 14px; padding: 15px 20px;
  cursor: pointer; display: flex; flex-direction: column;
  align-items: flex-start; gap: 4px;
  font-size: 13px; font-weight: 700;
  transition: all .15s;
}
.act-teal { background: rgba(0,235,200,.08); border: 1px solid rgba(0,235,200,.25); color: var(--navy); }
.act-navy { background: rgba(0,0,140,.07); border: 1px solid rgba(0,0,140,.18); color: var(--navy); }
.act-ind  { background: rgba(99,102,241,.07); border: 1px solid rgba(99,102,241,.2); color: var(--ind); }
.act-btn:hover { filter: brightness(1.03); transform: translateY(-1px); }
.act-sub { font-size: 11px; font-weight: 400; color: var(--sec); }

/* ── DROPDOWN INSTALACIONES ────────────────────────────── */
.inst-dd { position: absolute; top: calc(100% + 8px); left: 0; min-width: 220px; background: var(--surf); border-radius: 12px; border: 1px solid var(--brd); box-shadow: 0 8px 28px rgba(0,0,0,.16); z-index: 100; overflow: hidden; padding: 6px 0; }
.idd-title { font-size: 10px; font-weight: 700; color: var(--ter); letter-spacing: .08em; text-transform: uppercase; padding: 8px 16px 4px; }
.idd-item  { padding: 10px 16px; font-size: 12px; font-weight: 600; color: var(--pri); cursor: pointer; display: flex; align-items: center; gap: 8px; transition: background .12s; }
.idd-item:hover { background: rgba(0,235,200,.08); color: var(--navy); }
.idd-dot   { width: 7px; height: 7px; border-radius: 50%; background: var(--pos); box-shadow: 0 0 4px rgba(16,185,129,.7); flex-shrink: 0; }
.idd-current { padding: 10px 16px; font-size: 12px; font-weight: 700; color: var(--navy); display: flex; align-items: center; gap: 8px; background: rgba(0,235,200,.08); cursor: default; border-bottom: 1px solid var(--brd); }
.idd-check { font-size: 11px; color: var(--teal); flex-shrink: 0; }
.idd-here  { margin-left: auto; font-size: 9px; font-weight: 600; color: rgba(0,235,200,.8); letter-spacing: .04em; white-space: nowrap; }

.act-ico {
  font-family: 'Material Icons';
  font-size: 18px;
  font-style: normal;
  font-weight: normal;
  line-height: 1;
  color: inherit;
  margin-bottom: 2px;
}

/* ── RESPONSIVE ──────────────────────────────────────────────────── */
@media (max-width: 900px) {
  .kpi-grid   { grid-template-columns: repeat(2,1fr); }
  .cmp-grid   { grid-template-columns: 1fr; }
  .ic-metrics { grid-template-columns: 1fr; }
  .anal-grid  { grid-template-columns: 1fr; }
  .fp-grid    { grid-template-columns: 1fr; }
  .act-row    { grid-template-columns: 1fr; }
  .dem-bottom { grid-template-columns: 1fr; }
  .dem-stats  { grid-template-columns: repeat(3,1fr); }
  #s3em-content { padding: 4px 16px 40px; }
  .cfg-grid   { grid-template-columns: repeat(2,1fr); }
}

controllerScript.body:
/**
 * SUNKUU 360 — Template Pro EM (Shelly Pro EM-50, monofásico, 2 canales) · A-05 (2026-10-27), copia DEV
 * Derivado de "Sunkuu — Template 3EM" (FIX-01 + FEAT-01): mismo render; los datos se arman con los canales en uso
 * (bloque A-05 pem). Instalación, dispositivo, canales y etiqueta salen del registro (módulo registroMod, fail-closed).
 * Sin tarifa por defecto: sin tarifa_kwh el costo no se muestra. Plan: docs/arquitectura/2026-10-26-opcion-A-proem.md §3.
 *
 * Origen: SUNKUU 360 — Template 3EM · JS v2B
 * ThingsBoard PE 4.3.0PE
 *
 * v2B — Bloque 2B: Operational Intelligence Layer
 *  · classifyOperationalState(): clasifica en Estable / Atención / Riesgo / Sin histórico / Sin señal
 *  · tryRenderIntelligence(): card evolucionada con badge, título ejecutivo, impacto, acción, métricas
 *  · renderComparisons() llama a tryRenderIntelligence() al final para update con históricos
 *
 * SERVER ATTRIBUTES opcionales en el device:
 *   install_name, tarifa_kwh, alerta_fp_min, alerta_kw_max, voltaje_min, voltaje_max
 *
 * RECURSOS (pestaña Resources del widget type):
 *   https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js
 *   https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js
 */
self.onInit = function() {
  var ctx = self.ctx;

  /* ── CONFIG ────────────────────────────────────────────────────── */
  var DEVICE_ID = '', TARIFA = null, INSTALL_NAME = 'Instalación';   /* A-05: sin tarifa por defecto (P-A5) */
  var FP_MIN = 0.95, KW_MAX = 25, V_MIN = 209, V_MAX = 231;
  var EST_ALERT_H = 2, EST_DISC_H = 6;   /* FIX-01 · estado del encabezado: atributos estado_alerta_h / estado_desconexion_h */

  /* A-05 · Instalación desde el registro (sunkuu-registro.js, alias registroMod): dispositivo principal, canales en uso y
     etiqueta. Sin registro, sin instalación para este dashboard o de otro tipo: mensaje y ninguna consulta (fail-closed). */
  var REG = (typeof registroMod !== 'undefined' && registroMod && registroMod.loadInstallations) ? registroMod : window.SunkuuRegistro;
  var INST = null, CANALES = [];
  var DASH_ID = (window.location.pathname.match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi) || []).pop() || '';

  var EXPORT_DASH = '75c7e760-3200-11f1-a6d8-33f75efe8b97';
  ctx.$container.css({ 'overflow-y': 'auto', 'height': '100%' });

  /* ── ALMACÉN ───────────────────────────────────────────────────── */
  var D = {
    lat:{}, demand:{}, fp:{}, alarms:[], monthly:[],
    voltMin:{}, voltMax:{},
    energyToday:null, energyYesterday:null,
    energyWeekAgo:null, energy30DayAvg:null,
    energyYdFull:null, projKwh:null, projLoaded:false, hm:'',   /* FIX-01 */
    peakKw:null, peakHour:null, lastRealTs:null,
    loaded:{ lat:false, demand:false, fp:false }
  };

  var HDR_H = 94, container = ctx.$container[0], CH = {}, refreshTimer = null;

  /* ── CHART GUARD ───────────────────────────────────────────────── */
  function whenChart(cb) {
    if (typeof Chart !== 'undefined') { cb(); return; }
    var attempts = 0;
    var wait = setInterval(function() {
      attempts++;
      if (typeof Chart !== 'undefined') { clearInterval(wait); cb(); }
      else if (attempts > 40) { clearInterval(wait); console.warn('[3EM] Chart.js timeout'); }
    }, 250);
  }

  /* ── TIEMPO ────────────────────────────────────────────────────── */
  function nowMs()      { return Date.now(); }
  function todayStart() { return limaMidnight(0); }   /* FIX-01: medianoche de Lima, no la del navegador */
  function ydayStart()  { return todayStart()-86400000; }
  function daysAgo(n)   { return nowMs()-n*86400000; }

  /* ── API ───────────────────────────────────────────────────────── */
  function tsUrl(keys,startTs,endTs,interval,agg,limit){
    var u='/api/plugins/telemetry/DEVICE/'+DEVICE_ID+'/values/timeseries?keys='+keys;
    if(startTs!==undefined) u+='&startTs='+startTs+'&endTs='+endTs;
    if(interval) u+='&interval='+interval+'&agg='+(agg||'AVG');
    if(limit)    u+='&limit='+limit;
    return u;
  }
  /* FIX-01:BEGIN fx — contador de energía, mes en Lima, estado y sesión */
  var FX_H=3600000, FX_D=86400000, FX_LOOK=7*86400000, FX_MH=2*3600000;   /* FX_MH: tramo del mes (2 h): acota lo que pierde un reset del contador */
  var SESS={lost:false,pingTs:0};
  var SESSION_PING=true;   /* false = solo reintento, sin la llamada de renovación vía ctx.http */

  function fxUrl(dev,key,s,e,iv,ag,lim){
    var u='/api/plugins/telemetry/DEVICE/'+dev+'/values/timeseries?keys='+key+'&startTs='+s+'&endTs='+e;
    u+=iv?'&interval='+iv+'&agg='+ag:'&agg=NONE&orderBy=DESC';
    return u+'&limit='+lim;
  }

  /* Contador en el instante ts: último valor con ts' <= ts (limit=1, DESC). null = sin lectura previa; undefined = error */
  function fxCounterAt(dev,key,ts,cb){
    api(fxUrl(dev,key,ts-FX_LOOK,ts+1,0,'NONE',1),function(d){
      var a=d&&d[key]; cb(a&&a.length?parseFloat(a[0].value):null);
    },function(){ cb(undefined); });
  }

  /* Máximo del contador por tramo [t0+k·iv, t0+(k+1)·iv); undefined = tramo sin dato; null = error */
  function fxBuckets(dev,key,t0,t1,iv,cb){
    var n=Math.max(1,Math.ceil((t1-t0)/iv));
    api(fxUrl(dev,key,t0,t1,iv,'MAX',n+2),function(d){
      var a=(d&&d[key])||[], v=[], i;
      for(i=0;i<n;i++) v.push(undefined);
      a.forEach(function(p){
        var k=Math.floor((+p.ts-t0)/iv), x=parseFloat(p.value);
        if(k<0) k=0; if(k>=n) k=n-1;
        if(!isNaN(x)&&(v[k]===undefined||x>v[k])) v[k]=x;
      });
      cb(v);
    },function(){ cb(null); });
  }

  /* kWh por tramo a partir del contador (Wh). Tramo sin dato = 0 (arrastra el último valor);
     delta negativo (reset del contador) = 0; sin base, el primer valor es la base y su tramo es null. */
  function fxSteps(base,vals){
    var prev=base, out=[], i, v, d;
    for(i=0;i<vals.length;i++){
      v=vals[i];
      if(v===undefined||v===null||isNaN(v)){ out.push(prev===null?null:0); continue; }
      if(prev===null){ out.push(null); prev=v; continue; }
      d=v-prev; out.push(d>0?d/1000:0); prev=v;
    }
    return out;
  }
  function fxSum(steps,from,to){
    var s=0,n=0,i;
    for(i=from;i<to&&i<steps.length;i++){ if(steps[i]!==null){ s+=steps[i]; n++; } }
    return {sum:s,n:n};
  }

  /* Energía entre t0 y t1 (ms) con tramos de iv ms. cb(null) si falla; total=null si no hay base ni datos. */
  function fxEnergy(dev,key,t0,t1,iv,cb){
    var base,vals,got=0;
    function done(){
      if(++got<2) return;
      if(base===undefined||vals===null){ cb(null); return; }
      var st=fxSteps(base,vals), r=fxSum(st,0,st.length);
      cb({steps:st,total:r.n>0?r.sum:null,hasBase:base!==null});
    }
    fxCounterAt(dev,key,t0,function(b){ base=b; done(); });
    fxBuckets(dev,key,t0,t1,iv,function(v){ vals=v; done(); });
  }

  /* Mes en curso en hora Lima (UTC−5 explícito): inicio, fin, días y días ya cerrados */
  function fxMonth(){
    var t0=limaMidnight(0), d=new Date(t0+LIMA_OFFSET), y=d.getUTCFullYear(), m=d.getUTCMonth();
    var start=Date.UTC(y,m,1)-LIMA_OFFSET, end=Date.UTC(y,m+1,1)-LIMA_OFFSET;
    return {start:start,end:end,days:Math.round((end-start)/FX_D),closed:Math.round((t0-start)/FX_D)};
  }
  /* Método B: energía del mes a la fecha + promedio diario de los días cerrados × días restantes.
     closedDays puede ser fraccionario (tramos de 2 h con dato); se exige al menos 1 día cerrado. */
  function fxProject(mtd,closedSum,closedDays,now,monthEnd){
    if(mtd===null||!(closedDays>=1)) return null;
    return mtd+closedSum/closedDays*((monthEnd-now)/FX_D);
  }
  /* Energía del mes en hora Lima por tramos de 2 h; cb({mtd,projKwh}) o cb(null) si falla */
  function fxMonthEnergy(dev,key,now,cb){
    var M=fxMonth(), per=FX_D/FX_MH;
    fxEnergy(dev,key,M.start,now,FX_MH,function(r){
      if(!r){ cb(null); return; }
      var c=fxSum(r.steps,0,M.closed*per);
      cb({mtd:r.total,projKwh:fxProject(r.total,c.sum,c.n/per,now,M.end)});
    });
  }
  function fxPct(cur,ref){
    if(cur===null||cur===undefined||!(ref>0)||!isFinite(cur)) return null;
    return (cur-ref)/ref*100;
  }
  function fxFP(p,s){
    if(!(s>0)||p===null||p===undefined||isNaN(p)) return null;
    return Math.min(1,Math.abs(p)/s);
  }
  function fxHM(ts){
    var m=Math.floor((((ts+LIMA_OFFSET)%FX_D)+FX_D)%FX_D/60000);
    return (Math.floor(m/60)<10?'0':'')+Math.floor(m/60)+':'+(m%60<10?'0':'')+(m%60);
  }
  function fxAge(sec){
    if(sec<60) return 'hace '+sec+' seg';
    if(sec<3600) return 'hace '+Math.floor(sec/60)+' min';
    return 'hace '+Math.floor(sec/3600)+'h '+Math.floor((sec%3600)/60)+' min';
  }
  /* Estado según la antigüedad del último dato: ≤ alerta → En línea; > alerta → Sin datos recientes; > desconexión → Desconectado */
  function fxStatus(ageMs,alertH,discH){
    if(ageMs===null||ageMs===undefined||isNaN(ageMs)) return {k:'nodata',label:'Sin datos',color:'#96AABF'};
    if(ageMs>discH*FX_H)  return {k:'disc', label:'Desconectado',        color:'#EF4444'};
    if(ageMs>alertH*FX_H) return {k:'stale',label:'Sin datos recientes', color:'#F59E0B'};
    return {k:'ok',label:'En línea',color:'#10B981'};
  }

  /* Sesión: lee el token en cada llamada; ante 401 pide a TB que lo renueve, reintenta una vez a los 2 s
     y, si sigue fallando, avisa en el encabezado ("Sesión expirada — recargar"). */
  function sessionPing(){
    if(!SESSION_PING) return;
    var t=Date.now(); if(t-SESS.pingTs<5000) return; SESS.pingTs=t;
    try{ ctx.http.get('/api/auth/user').subscribe(function(){},function(){}); }catch(e){}
  }
  function sessionLost(){ if(SESS.lost) return; SESS.lost=true; try{ updateLastSeen(); }catch(e){} }
  function sessionBack(){ if(!SESS.lost) return; SESS.lost=false; try{ updateLastSeen(); }catch(e){} }
  function api(url, ok, fail) {
    function go(retried){
      var token = localStorage.jwt_token || '';
      fetch(url, {headers:{'X-Authorization':'Bearer '+token}})
        .then(function(r){ if(r.status===401) return Promise.reject({auth:true}); return r.ok ? r.json() : Promise.reject(r.status); })
        .then(function(d){ sessionBack(); return ok(d); })
        .catch(function(e){
          if(e && e.auth){
            if(!retried){ sessionPing(); setTimeout(function(){ go(true); }, 2000); return; }
            sessionLost(); e=401;
          }
          if(fail) fail(e); else console.warn('[3EM]',e);
        });
    }
    go(false);
  }
  /* FIX-01:END fx */

  /* A-05:BEGIN pem — Shelly Pro EM-50 sobre el render del 3EM ─────────────────────────────────
     Cada clave del 3EM se arma con los canales en uso de la instalación (registro, A-03):
       *_total  = suma de los canales en uso (potencia activa y aparente, energía y energía devuelta);
       *_fase_a = 1.er canal en uso (canal 0); *_fase_b = 2.º canal en uso (canal 1, si tiene nombre); no hay *_fase_c;
       voltaje  = el del canal 0 en las columnas en uso (el equipo tiene una sola entrada de tensión).
     Último valor: suma de los canales que tienen dato y la hora del más reciente (el estado usa el dato más reciente
     de cualquier canal en uso; un canal que nunca publicó no suma). Series (curvas, energía): un tramo solo tiene total
     si todos los canales en uso tienen ese tramo; sin el de un canal no se muestra un total parcial. La energía usa las
     funciones de FIX-01 tal cual, una vez por canal, y se suma (pemEnergy, pemMonthEnergy). */
  var PH_COL=['#00EBC8','#00008C','#6366F1'];
  function phOn(i){ return !!CANALES[i]; }
  function phL(i){ return CANALES[i]?CANALES[i].nombre:''; }
  function esc(s){ return String(s===null||s===undefined?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); }
  function pemSol(kwh){ return TARIFA>0?fmtSol(kwh*TARIFA):'Sin tarifa (tarifa_kwh)'; }
  function pemMap(k){
    var m=/^(.+)_(total|fase_a|fase_b|fase_c)$/.exec(k); if(!m||!CANALES.length) return null;
    var b=m[1], s=m[2], i={fase_a:0,fase_b:1,fase_c:2}[s];
    if(b==='voltaje') return s!=='total'&&phOn(i)?{one:'voltaje_canal_'+CANALES[0].n}:null;
    if(s==='total') return /^(potencia_activa|potencia_aparente|energia|energia_ret)$/.test(b)?{sum:CANALES.map(function(c){return b+'_canal_'+c.n;})}:null;
    return phOn(i)?{one:b+'_canal_'+CANALES[i].n}:null;
  }
  function pemSumLatest(arrs){
    var ok=arrs.filter(function(a){return a&&a.length&&!isNaN(parseFloat(a[0].value));});
    if(!ok.length) return null;
    var v=0,ts=0; ok.forEach(function(a){ v+=parseFloat(a[0].value); ts=Math.max(ts,+a[0].ts); });
    return [{ts:ts,value:String(v)}];
  }
  function pemSumSerie(arrs){
    if(arrs.some(function(a){return !a||!a.length;})) return null;
    var by=arrs.slice(1).map(function(a){var o={};a.forEach(function(p){o[+p.ts]=p;});return o;}), out=[];
    arrs[0].forEach(function(p){
      var v=parseFloat(p.value), ok=!isNaN(v);
      by.forEach(function(o){ var q=o[+p.ts], x=q?parseFloat(q.value):NaN; if(isNaN(x)) ok=false; else v+=x; });
      if(ok) out.push({ts:p.ts,value:String(v)});
    });
    return out;
  }
  /* Igual que api() sobre tsUrl() con claves del 3EM: pide las claves reales de los canales y devuelve las del 3EM */
  function vApi(keys,urlFn,ok,fail){
    var map={}, real=[];
    String(keys).split(',').forEach(function(k){
      var r=pemMap(k); if(!r) return; map[k]=r;
      (r.sum||[r.one]).forEach(function(x){ if(real.indexOf(x)<0) real.push(x); });
    });
    if(!real.length){ setTimeout(function(){ ok({}); },0); return; }
    var url=urlFn(real.join(',')), serie=url.indexOf('&startTs=')>=0;
    api(url,function(d){
      d=d||{}; var out={};
      Object.keys(map).forEach(function(k){
        var r=map[k], a=r.one?d[r.one]:(serie?pemSumSerie:pemSumLatest)(r.sum.map(function(x){return d[x];}));
        if(a&&a.length) out[k]=a.slice();
      });
      return ok(out);
    },fail);
  }
  /* Energía de los canales en uso con fxEnergy (FIX-01) y suma. Un canal que falla o sin dato → null (no se suma parcial) */
  function pemEnergy(t0,t1,iv,cb){
    var res=[], left=CANALES.length;
    CANALES.forEach(function(c,i){
      fxEnergy(DEVICE_ID,'energia_canal_'+c.n,t0,t1,iv,function(r){
        res[i]=r; if(--left) return;
        if(res.some(function(x){return !x;})){ cb(null); return; }
        var steps=res[0].steps.map(function(s,j){
          var t=0; for(var k=0;k<res.length;k++){ var x=res[k].steps[j]; if(x===null||x===undefined) return null; t+=x; } return t;
        });
        var tot=res.some(function(x){return x.total===null;})?null:res.reduce(function(a,x){return a+x.total;},0);
        cb({steps:steps,total:tot,hasBase:res.every(function(x){return x.hasBase;})});
      });
    });
  }
  function pemMonthEnergy(now,cb){
    var res=[], left=CANALES.length;
    CANALES.forEach(function(c,i){
      fxMonthEnergy(DEVICE_ID,'energia_canal_'+c.n,now,function(m){
        res[i]=m; if(--left) return;
        if(res.some(function(x){return !x;})){ cb(null); return; }
        function suma(k){ return res.some(function(x){return x[k]===null||x[k]===undefined;})?null:res.reduce(function(a,x){return a+x[k];},0); }
        cb({mtd:suma('mtd'),projKwh:suma('projKwh')});
      });
    });
  }
  /* Encabezado, columnas, leyendas y tarjetas según los canales en uso */
  function pemSetup(){
    set('hdr-inst-name',INSTALL_NAME);
    ['a','b','c'].forEach(function(x,i){
      var th=el('th-ph-'+x); if(th){ th.style.display=phOn(i)?'':'none'; th.innerHTML='<span class="ph-dot" style="background:'+PH_COL[i]+'"></span>'+esc(phL(i)); }
      var lg=el('leg-fase-'+x); if(lg) lg.innerHTML='<span class="leg-dot" style="background:'+PH_COL[i]+'"></span>'+esc(phL(i));
      var fc=el('fp-'+x); if(fc&&!phOn(i)) fc.style.display='none';
    });
    var sb=el('dem-series-btns'); if(sb&&CANALES.length<2) sb.style.display='none';
  }
  function pemMensaje(t){
    ctx.$container[0].innerHTML=
      '<div style="display:flex;align-items:center;justify-content:center;height:200px;font-family:system-ui;color:#5A6E8A;flex-direction:column;gap:12px;text-align:center;padding:0 16px">'+
      '<span style="font-family:\'Material Icons\';font-size:36px;color:#96AABF">info</span><strong>'+t+'</strong></div>';
  }
  /* A-05:END pem */

  /* ── DOM ───────────────────────────────────────────────────────── */
  function el(id)      { return document.getElementById(id); }
  function set(id,val) { var e=el(id); if(e) e.textContent=val; }
  function html(id,v)  { var e=el(id); if(e) e.innerHTML=v; }
  function fmtV(v)     { return parseFloat(v).toFixed(1); }
  function fmtFP(f)    { return parseFloat(f).toFixed(2); }
  function fmtSol(s)   { return 'S/ '+s.toFixed(2); }
  function fpNow()     { var f=fxFP(lat('potencia_activa_total'),lat('potencia_aparente_total')); return f===null?0:f; }   /* FIX-01: FP = P_total / S_total */
  function fmtTs(ts)   { var d=new Date(ts); return pad(d.getDate())+'/'+pad(d.getMonth()+1)+' '+pad(d.getHours())+':00h'; }
  function pad(n)      { return n<10?'0'+n:''+n; }
  function lat(key)    { return D.lat[key]!==undefined?D.lat[key]:0; }

