  /* ── ANCHOR NAV ────────────────────────────────────────────────── */
  document.querySelectorAll('.anc').forEach(function(btn){
    btn.addEventListener('click',function(){
      var section=el(this.getAttribute('data-t')); if(!section) return;
      if(container.scrollHeight > container.clientHeight + 5){
        var y=container.scrollTop+(section.getBoundingClientRect().top-container.getBoundingClientRect().top)-(HDR_H+20);
        container.scrollTo({top:y,behavior:'smooth'});
      } else {
        var y=section.getBoundingClientRect().top+window.pageYOffset-HDR_H-20;
        window.scrollTo({top:y,behavior:'smooth'});
      }
      document.querySelectorAll('.anc').forEach(function(b){b.classList.remove('active');});
      this.classList.add('active');
    });
  });
  function updateActiveAnchor(){
    var sections=['sec01','sec02','sec03','sec04','sec05'];
    var current=sections[0];
    var cTop=container.getBoundingClientRect().top;
    sections.forEach(function(id){
      var s=document.getElementById(id); if(!s) return;
      if(s.getBoundingClientRect().top-cTop<=HDR_H+30) current=id;
    });
    document.querySelectorAll('.anc').forEach(function(b){b.classList.remove('active');});
    var btn=document.querySelector('.anc[data-t="'+current+'"]');
    if(btn) btn.classList.add('active');
  }
  container.addEventListener('scroll', updateActiveAnchor);
  window.addEventListener('scroll', updateActiveAnchor);

  /* ── LAST SEEN ─────────────────────────────────────────────────── */
  function updateLastSeen(){
    var now=new Date();
    var t=pad(now.getHours())+':'+pad(now.getMinutes())+':'+pad(now.getSeconds());
    var dot=document.querySelector('#s3em-hdr .status-dot'), txt=document.querySelector('#s3em-hdr .status-text');
    function hdr(label,color,extra){
      if(dot) dot.style.background=color;
      if(txt) txt.innerHTML=label+(extra?' · ':'')+'<span id="last-update">'+(extra||'')+'</span>';
    }
    if(SESS.lost){ hdr('Sesión expirada — recargar','#EF4444',''); return; }
    if(D.lastRealTs){
      var ageMs=Math.max(0,now.getTime()-D.lastRealTs), ageStr=fxAge(Math.floor(ageMs/1000));
      var st=fxStatus(ageMs,EST_ALERT_H,EST_DISC_H);
      set('last-sec', ageStr);
      var lastEl=el('last-sec');
      if(lastEl) lastEl.style.color=st.k==='disc'?'#EF4444':st.k==='stale'?'#F59E0B':'#5A6E8A';
      hdr(st.label,st.color,st.k==='ok'?t:ageStr);
    } else {
      set('last-sec','Sin datos');
      hdr('Sin datos','#96AABF','');
    }
  }

  /* ══════════════════════════════════════════════════════════════════
     SERVER ATTRIBUTES
  ══════════════════════════════════════════════════════════════════ */
  function loadServerAttributes(){
    api('/api/plugins/telemetry/DEVICE/'+DEVICE_ID+'/values/attributes/SERVER_SCOPE',
      function(attrs){
        if(attrs && attrs.length){
          attrs.forEach(function(a){
            switch(a.key){
              /* A-05: install_name no se usa (la etiqueta sale del registro) */
              case 'tarifa_kwh':    TARIFA  = parseFloat(a.value) || TARIFA;  break;
              case 'alerta_fp_min': FP_MIN  = parseFloat(a.value) || FP_MIN;  break;
              case 'alerta_kw_max': KW_MAX  = parseFloat(a.value) || KW_MAX;  break;
              case 'voltaje_min':   V_MIN   = parseFloat(a.value) || V_MIN;   break;
              case 'voltaje_max':   V_MAX   = parseFloat(a.value) || V_MAX;   break;
              case 'estado_alerta_h':      EST_ALERT_H = parseFloat(a.value) || EST_ALERT_H; break;
              case 'estado_desconexion_h': EST_DISC_H  = parseFloat(a.value) || EST_DISC_H;  break;
            }
          });
        }
        if(!(EST_DISC_H>EST_ALERT_H)){ EST_ALERT_H=2; EST_DISC_H=6; }
        var instEl = el('hdr-inst-name');
        if(instEl) instEl.textContent = INSTALL_NAME;
        renderCfgPanel(); updateLastSeen(); renderCostText(); renderSec01KpiEnergy(); tryRenderIntelligence();   /* A-05: la tarifa llega aquí */
      },
      function(){
        var instEl = el('hdr-inst-name');
        if(instEl) instEl.textContent = INSTALL_NAME;
        renderCfgPanel();
      }
    );
  }

  /* ══════════════════════════════════════════════════════════════════
     CARGA DE DATOS
  ══════════════════════════════════════════════════════════════════ */
  var ALL_KEYS=[
    'potencia_activa_total','potencia_activa_fase_a','potencia_activa_fase_b','potencia_activa_fase_c',
    'potencia_aparente_total','potencia_aparente_fase_a','potencia_aparente_fase_b','potencia_aparente_fase_c',
    'energia_total','energia_fase_a','energia_fase_b','energia_fase_c',
    'energia_ret_total','energia_ret_fase_a','energia_ret_fase_b','energia_ret_fase_c',
    'voltaje_fase_a','voltaje_fase_b','voltaje_fase_c',
    'corriente_fase_a','corriente_fase_b','corriente_fase_c',
    'factor_potencia_fase_a','factor_potencia_fase_b','factor_potencia_fase_c'
  ].join(',');

  function loadLatest(){
    vApi(ALL_KEYS,function(k){return tsUrl(k);},function(d){
      var flat={};
      Object.keys(d).forEach(function(k){
        if(d[k]&&d[k].length>0) flat[k]=parseFloat(d[k][0].value);
      });
      D.lat=flat; D.loaded.lat=true;
      /* Guardar timestamp real del último dato recibido desde TB */
      if(d.potencia_activa_total&&d.potencia_activa_total.length>0){
        D.lastRealTs=+d.potencia_activa_total[0].ts;
      }
      updateLastSeen(); renderSec01(); renderSec03(); if(D.energy30DayAvg!==null) tryRenderIntelligence();
      if(D.loaded.fp) renderSec05NoChart();
    });
  }

  /* FIX-01 · Energía por diferencia de contador (último valor ≤ instante). Día = 00:00–24:00 Lima.
     Comparativos en el mismo tramo (00:00 → hora actual). Proyección = mes a la fecha + promedio de días cerrados × días restantes. */
  function loadEnergyDaily(){
    var now=nowMs(), t0=limaMidnight(0);
    pemEnergy(t0,now,FX_H,function(r){
      D.energyToday=r?r.total:null; D.hm=fxHM(now);
      renderSec01KpiEnergy(); tryRenderIntelligence();
      loadEnergyCompare(now,t0); load30DayAverage(t0); loadMonthProjection(now);
    });
  }

  function loadEnergyCompare(now,t0){
    pemEnergy(t0-FX_D,now-FX_D,FX_H,function(r){
      D.energyYesterday=r?r.total:null; renderComparisons();
    });
    pemEnergy(t0-7*FX_D,now-7*FX_D,FX_H,function(r){
      D.energyWeekAgo=r?r.total:null; renderComparisons();
    });
  }

  function load30DayAverage(t0){
    pemEnergy(t0-30*FX_D,t0,FX_D,function(r){
      D.energy30DayAvg=null; D.energyYdFull=null;
      if(r){
        var pos=r.steps.filter(function(s){return s!==null&&s>0;});
        if(pos.length>=7) D.energy30DayAvg=pos.reduce(function(a,b){return a+b;},0)/pos.length;
        var last=r.steps[r.steps.length-1];
        D.energyYdFull=(last!==null&&last>0)?last:null;
      }
      renderComparisons();
    });
  }

  function loadMonthProjection(now){
    pemMonthEnergy(now,function(m){
      D.projKwh=m?m.projKwh:null; D.projLoaded=true;
      renderSec01KpiEnergy(); renderCostText(); tryRenderIntelligence();
    });
  }

  function loadAlarms(){
    api('/api/alarm/DEVICE/'+DEVICE_ID+'?page=0&pageSize=10&fetchOriginator=false&statusList=ACTIVE_UNACK,ACTIVE_ACK',
      function(d){D.alarms=(d&&d.data)?d.data:[];renderAlarms();},
      function(){
        api('/api/alarm/DEVICE/'+DEVICE_ID+'?page=0&pageSize=10&fetchOriginator=false',
          function(d){D.alarms=(d&&d.data)?d.data:[];renderAlarms();},
          function(){D.alarms=[];renderAlarms();}
        );
      }
    );
  }

  function loadVoltageRange(){
    var keys='voltaje_fase_a,voltaje_fase_b,voltaje_fase_c';
    var intv=Math.max(nowMs()-todayStart(),60000);
    vApi(keys,function(k){return tsUrl(k,todayStart(),nowMs(),intv,'MIN',5);},function(d){D.voltMin=d;updateVoltRange();});
    vApi(keys,function(k){return tsUrl(k,todayStart(),nowMs(),intv,'MAX',5);},function(d){D.voltMax=d;updateVoltRange();});
  }

  function loadDemand(){
    var keys='potencia_activa_total,potencia_activa_fase_a,potencia_activa_fase_b,potencia_activa_fase_c';
    vApi(keys,function(k){return tsUrl(k,daysAgo(1),nowMs(),3600000,'AVG',100);},function(d){
      D.demand=d; D.loaded.demand=true;
      computePeak(); tryRenderIntelligence();
      whenChart(function(){ renderSec02(); renderSec04(); });
    });
  }

  function loadFP(){
    var keys='factor_potencia_fase_a,factor_potencia_fase_b,factor_potencia_fase_c';
    vApi(keys,function(k){return tsUrl(k,daysAgo(1),nowMs(),3600000,'AVG',100);},function(d){
      D.fp=d; D.loaded.fp=true;
      renderSec05NoChart();
      whenChart(function(){ renderSec05Chart(); });
    });
  }

  function loadMonthly(){
    vApi('energia_total',function(k){return tsUrl(k,daysAgo(180),nowMs(),30*86400000,'MAX',20);},function(d){
      var pts=(d.energia_total||[]).map(function(p){return{ts:+p.ts,v:parseFloat(p.value)};});
      pts.sort(function(a,b){return a.ts-b.ts;});
      D.monthly=pts;
      whenChart(function(){ renderCostCard(); });
    });
  }

  function computePeak(){
    var total=D.demand&&D.demand.potencia_activa_total;
    if(!total||total.length===0) return;
    var maxV=-Infinity,maxTs=null;
    total.forEach(function(p){var v=parseFloat(p.value);if(v>maxV){maxV=v;maxTs=p.ts;}});
    D.peakKw=maxV/1000; D.peakHour=maxTs; tryRenderIntelligence();
  }

  /* ══════════════════════════════════════════════════════════════════
     2B — ESTADO OPERATIVO
  ══════════════════════════════════════════════════════════════════ */
  function classifyOperationalState() {
    if (!D.loaded.lat) {
      return {
        level:'sin-senal', badge:'Sin señal',
        title:'No se reciben datos recientes del dispositivo.',
        impact:'No es posible evaluar el estado operativo. Verificar conectividad del sensor.',
        action:'Revisar conexión MQTT del dispositivo.', metrics:null
      };
    }
    if (D.energy30DayAvg === null) {
      return {
        level:'sin-historico', badge:'Sin histórico suficiente',
        title:'Monitoreo activo. Aún no hay suficiente histórico para detectar patrones confiables.',
        impact:null,
        action:'El análisis comparativo estará disponible tras 30 días de datos en plataforma.',
        metrics:buildMetrics()
      };
    }
    var vA=lat('voltaje_fase_a'), vB=lat('voltaje_fase_b'), vC=lat('voltaje_fase_c');
    var voltDeviation=0;
    [vA,vB,vC].forEach(function(v){
      if(!v) return;
      var dev=Math.max(v<V_MIN?V_MIN-v:0, v>V_MAX?v-V_MAX:0);
      if(dev>voltDeviation) voltDeviation=dev;
    });
    var fp=fpNow();
    var en=D.energyYdFull;   /* FIX-01: día cerrado (ayer) contra el promedio de días cerrados */
    var consumoSobrePatron=fxPct(en,D.energy30DayAvg);

    /* Riesgo: voltaje >10V fuera de límite, confirmado con histórico */
    if(voltDeviation>10){
      var voltHistConfirm=false, hasHistVolt=false;
      ['voltaje_fase_a','voltaje_fase_b','voltaje_fase_c'].forEach(function(k){
        var mn=D.voltMin[k],mx=D.voltMax[k]; if(!mn||!mx||!mn[0]||!mx[0]) return;
        hasHistVolt=true;
        var mnV=parseFloat(mn[0].value), mxV=parseFloat(mx[0].value);
        if((mnV<V_MIN-10)||(mxV>V_MAX+10)) voltHistConfirm=true;
      });
      if(!hasHistVolt) voltHistConfirm=true;
      if(voltHistConfirm){
        return {
          level:'riesgo', badge:'Riesgo operativo',
          title:'Voltaje fuera del rango operativo configurado ('+V_MIN+'–'+V_MAX+' V). Condición que puede afectar equipos conectados.',
          impact:'Equipos sensibles pueden operar fuera de especificación. Evaluar origen de la anomalía.',
          action:'Verificar calidad de suministro eléctrico y protecciones de la instalación.',
          metrics:buildMetrics()
        };
      }
    }

    /* Atención */
    var atencionReasons=[];
    if(fp>0&&fp<FP_MIN) atencionReasons.push('Factor de Potencia por debajo del mínimo configurado ('+fmtFP(fp)+')');
    if(voltDeviation>=5&&voltDeviation<=10) atencionReasons.push('Voltaje con desviación leve respecto al rango configurado');
    if(consumoSobrePatron!==null&&consumoSobrePatron>15) atencionReasons.push('Consumo de ayer superior al patrón reciente ('+consumoSobrePatron.toFixed(0)+'% sobre el promedio de 30 días)');

    if(atencionReasons.length>0){
      var impactMsg='';
      if(fp>0&&fp<FP_MIN) impactMsg='Un FP sostenido bajo el umbral puede generar sobrecostos tarifarios y reducir la vida útil de equipos.';
      else if(voltDeviation>=5) impactMsg='Fluctuaciones de voltaje pueden afectar equipos sensibles si se mantienen.';
      else impactMsg='Consumo elevado respecto al patrón puede indicar cambios en la operación o ineficiencias.';
      return {
        level:'atencion', badge:'Atención requerida',
        title:atencionReasons[0]+'.'+(atencionReasons.length>1?' También: '+atencionReasons.slice(1).join('; ')+'.':''),
        impact:impactMsg,
        action:atencionReasons.length>1?'Se detectaron '+atencionReasons.length+' condiciones que merecen seguimiento.':'Monitorear evolución durante las próximas horas.',
        metrics:buildMetrics()
      };
    }

    /* Estable */
    var consumoCtx='';
    if(consumoSobrePatron!==null){
      if(Math.abs(consumoSobrePatron)<=5) consumoCtx=' El consumo se mantiene alineado con el patrón histórico.';
      else if(consumoSobrePatron<0) consumoCtx=' El consumo de ayer estuvo '+Math.abs(consumoSobrePatron).toFixed(0)+'% por debajo del patrón reciente.';
    }
    return {
      level:'estable', badge:'Operación estable',
      title:'La instalación mantiene consumo y calidad eléctrica dentro de los parámetros configurados.'+consumoCtx,
      impact:null, action:null, metrics:buildMetrics()
    };
  }

  function buildMetrics(){
    var fp=fpNow();
    var pa=lat('potencia_activa_total');
    var vA=lat('voltaje_fase_a');
    var items=[];
    if(fp>0)  items.push({l:'Factor de Potencia', v:fmtFP(fp),              warn:fp<FP_MIN});
    if(pa>0)  items.push({l:'Demanda actual',      v:(pa/1000).toFixed(1)+' kW', warn:pa/1000>KW_MAX});
    if(vA>0)  items.push({l:'Voltaje',      v:fmtV(vA)+' V',         warn:vA<V_MIN-5||vA>V_MAX+5});
    if(D.energyToday!==null){
      items.push({l:'Consumo hoy'+(D.hm?' (hasta '+D.hm+')':''), v:D.energyToday.toFixed(1)+' kWh', warn:false});
    }
    return items;
  }

  function tryRenderIntelligence(){
    if(!D.loaded.lat) return;
    var state=classifyOperationalState();
    /* 2B-v2: Banda semántica — colores para fondo navy */
    var BAND={
      'estable':       {color:'#10B981',icon:'check_circle',   label:'OPERACIÓN ESTABLE'},
      'sin-historico': {color:'rgba(255,255,255,.28)',icon:'hourglass_empty',label:'SIN HISTÓRICO SUFICIENTE'},
      'atencion':      {color:'#F59E0B',icon:'warning_amber',  label:'ATENCIÓN REQUERIDA'},
      'riesgo':        {color:'#EF4444',icon:'error',          label:'RIESGO OPERATIVO'},
      'sin-senal':     {color:'rgba(255,255,255,.18)',icon:'signal_wifi_off',label:'SIN SEÑAL'}
    };
    var COLORS={
      'estable':       {bg:'rgba(16,185,129,.1)',   border:'#10B981',badge_bg:'#ECFDF5',          badge_text:'#10B981',text:'#065F46'},
      'sin-historico': {bg:'rgba(150,170,191,.08)', border:'#96AABF',badge_bg:'rgba(150,170,191,.12)',badge_text:'#5A6E8A',text:'#5A6E8A'},
      'atencion':      {bg:'rgba(245,158,11,.08)',  border:'#F59E0B',badge_bg:'rgba(245,158,11,.12)', badge_text:'#D97706',text:'#92400E'},
      'riesgo':        {bg:'rgba(239,68,68,.08)',   border:'#EF4444',badge_bg:'rgba(239,68,68,.1)',   badge_text:'#DC2626',text:'#7F1D1D'},
      'sin-senal':     {bg:'rgba(150,170,191,.08)', border:'#96AABF',badge_bg:'rgba(150,170,191,.12)',badge_text:'#5A6E8A',text:'#5A6E8A'}
    };
    var ICONS={'estable':'check_circle','sin-historico':'hourglass_empty','atencion':'warning_amber','riesgo':'error','sin-senal':'signal_wifi_off'};
    var col=COLORS[state.level]||COLORS['sin-historico'];
    var icon=ICONS[state.level]||'info';
    var now=new Date(), t=pad(now.getHours())+':'+pad(now.getMinutes())+':'+pad(now.getSeconds());

    var metricsHtml='';
    if(state.metrics&&state.metrics.length>0){
      metricsHtml='<div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:14px;padding-top:12px;border-top:1px solid rgba(212,224,238,.6)">'+
        state.metrics.map(function(m){
          var ws=m.warn?'background:rgba(245,158,11,.18);border-color:rgba(245,158,11,.4);color:#FBBF24':'background:rgba(255,255,255,.07);border-color:rgba(255,255,255,.12);color:rgba(255,255,255,.75)';
          return '<div style="display:flex;flex-direction:column;gap:2px;padding:7px 12px;border-radius:8px;border:1px solid;'+ws+'">'+
            '<span style="font-size:9px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;color:rgba(255,255,255,.4);margin-bottom:2px;display:block">'+m.l+'</span>'+
            '<span style="font-size:13px;font-weight:700">'+m.v+'</span></div>';
        }).join('')+'</div>';
    }
    var impactHtml=state.impact
      ?'<div style="margin-top:8px;font-size:12px;color:rgba(255,255,255,.6);line-height:1.6;margin-bottom:'+(state.action?'6px':'0')+'"><span style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:rgba(255,255,255,.3);margin-right:6px">Impacto potencial:</span>'+state.impact+'</div>':'';
    var actionHtml=state.action
      ?'<div style="margin-top:6px;font-size:12px;color:rgba(255,255,255,.5);line-height:1.6"><span style="font-family:Material Icons;font-size:12px;vertical-align:middle;margin-right:4px;color:rgba(255,255,255,.35)">arrow_forward</span>'+state.action+'</div>':''
    var band=BAND[state.level]||BAND['sin-historico'];
    var bandaHtml=
      '<div style="background:'+band.color+';border-radius:10px;padding:10px 16px;display:flex;align-items:center;gap:10px;margin-bottom:16px">'+
        '<span style="font-family:Material Icons;font-size:18px;color:white;line-height:1">'+band.icon+'</span>'+
        '<span style="font-size:12px;font-weight:800;letter-spacing:.08em;color:white;flex:1">'+band.label+'</span>'+
        '<span style="font-size:11px;color:rgba(255,255,255,.75);font-variant-numeric:tabular-nums">'+t+'</span>'+
      '</div>';
    var htmlContent=bandaHtml+
      '<div style="font-size:13px;font-weight:500;color:rgba(255,255,255,.92);line-height:1.65;margin-bottom:'+(state.impact||state.action?'10px':'0')+'">'+state.title+'</div>'+
      impactHtml+actionHtml+metricsHtml

    var icText=el('ic-text'); if(icText) icText.innerHTML=htmlContent;
    set('ic-date','Actualizado hoy '+t+' · análisis basado en telemetría real');

    /* Métricas externas icm-1/2/3 */
    if(D.energyToday!==null){
      var pctAyer=fxPct(D.energyToday,D.energyYesterday);
      if(pctAyer!==null){
        var col1=pctAyer>=0?'#EF4444':'#10B981';
        set('icm-1',(pctAyer>=0?'↑ +':'↓ ')+Math.abs(pctAyer).toFixed(1)+'%');
        set('icm-1s','misma franja horaria de ayer');
        var icm1=el('icm-1'); if(icm1) icm1.style.color=col1;
      }
    }
    if(D.projKwh!==null){
      set('icm-2','~'+Math.round(D.projKwh).toLocaleString('es-PE')+' kWh');
      set('icm-2s',TARIFA>0?'≈ '+fmtSol(D.projKwh*TARIFA)+' (solo energía)':'Sin tarifa (tarifa_kwh)');
    } else if(D.projLoaded){
      set('icm-2','—'); set('icm-2s','disponible desde el 2.º día del mes');
    }
    if(D.peakKw){
      set('icm-3',D.peakKw.toFixed(1)+' kW');
      set('icm-3s',D.peakHour?(function(){var d=new Date(D.peakHour);return pad(d.getHours())+':00h';})():'—');
    }
  }

  /* ══════════════════════════════════════════════════════════════════
     SECCIÓN 01
  ══════════════════════════════════════════════════════════════════ */
  function renderSec01(){
    var pa=lat('potencia_activa_total');
    var fpT=fxFP(lat('potencia_activa_total'),lat('potencia_aparente_total')), fp=fpT===null?0:fpT;
    set('kv-pa',Math.round(pa).toLocaleString('es-PE'));
