      if(fpT===null)      {fpEl.textContent='Sin dato';    fpEl.className='kc-chip';}
      else if(fp>=0.97)        {fpEl.textContent='Excelente';   fpEl.className='kc-chip ok';}
      else if(fp>=FP_MIN) {fpEl.textContent='Aceptable';   fpEl.className='kc-chip warn';}
      else                {fpEl.textContent='Bajo — revisar';fpEl.className='kc-chip alert';}
    }
  }

  function renderSec01KpiEnergy(){
