      if(semSEl) semSEl.textContent=hm+'Hoy: '+en.toFixed(1)+' kWh / Hace 7 d: '+D.energyWeekAgo.toFixed(1)+' kWh';
      if(semIco){semIco.textContent=upS?'trending_up':'trending_down';semIco.style.fontFamily='Material Icons';semIco.style.background=colS+'14';semIco.style.color=colS;semIco.style.borderColor=colS+'22';}
    } else {
      if(semEl)  semEl.textContent='Sin histórico';
      if(semSEl) semSEl.textContent='Disponible tras 7 días de datos en plataforma';
      if(semIco){semIco.textContent='history';semIco.style.fontFamily='Material Icons';semIco.style.background='rgba(150,170,191,.1)';semIco.style.color='#96AABF';semIco.style.borderColor='rgba(150,170,191,.2)';}
    }
    var d30El=el('cmp-30'),d30SEl=el('cmp-30-s'),d30Ico=el('cmp-icon-30');
    var pct3=fxPct(D.energyYdFull,D.energy30DayAvg);
    if(pct3!==null){
      var up3=pct3>=0, col3=up3?'#EF4444':'#10B981';
      if(d30El)  d30El.textContent=(up3?'↑ +':'↓ ')+Math.abs(pct3).toFixed(1)+'%';
      if(d30SEl) d30SEl.textContent='Ayer: '+D.energyYdFull.toFixed(1)+' kWh / Prom. 30 d: '+D.energy30DayAvg.toFixed(1)+' kWh';
      if(d30Ico){d30Ico.textContent=up3?'trending_up':'trending_down';d30Ico.style.fontFamily='Material Icons';d30Ico.style.background=col3+'14';d30Ico.style.color=col3;d30Ico.style.borderColor=col3+'22';}
    } else {
      if(d30El)  d30El.textContent='Sin histórico';
      if(d30SEl) d30SEl.textContent='Disponible tras 30 días de datos en plataforma';
      if(d30Ico){d30Ico.textContent='history';d30Ico.style.fontFamily='Material Icons';d30Ico.style.background='rgba(150,170,191,.1)';d30Ico.style.color='#96AABF';d30Ico.style.borderColor='rgba(150,170,191,.2)';}
    }
    /* 2B: actualizar estado operativo cuando llegan históricos */
