  /* ══════════════════════════════════════════════════════════════════
     SECCIÓN 02
  ══════════════════════════════════════════════════════════════════ */
  function renderSec02(){
    var rawA=D.demand.potencia_activa_fase_a||[], rawB=D.demand.potencia_activa_fase_b||[];
    var rawC=D.demand.potencia_activa_fase_c||[], rawT=D.demand.potencia_activa_total||[];
    if(rawT.length===0) return;
    var labels=rawT.map(function(p){var d=new Date(+p.ts);return pad(d.getHours())+':'+pad(d.getMinutes());});
    var dA=rawA.map(function(p){return parseFloat(p.value)/1000;}), dB=rawB.map(function(p){return parseFloat(p.value)/1000;});
    var dC=rawC.map(function(p){return parseFloat(p.value)/1000;}), dT=rawT.map(function(p){return parseFloat(p.value)/1000;});
    var vals=dT.slice(), maxV=Math.max.apply(null,vals), minV=Math.min.apply(null,vals);
    var avgV=vals.reduce(function(a,b){return a+b;},0)/vals.length;
    var maxIdx=vals.indexOf(maxV), minIdx=vals.indexOf(minV);
    set('ds-peak-v',maxV.toFixed(2)+' kW'); set('ds-avg-v',avgV.toFixed(2)+' kW'); set('ds-min-v',minV.toFixed(2)+' kW');
    if(rawT[maxIdx]) set('ds-peak-h',fmtTs(rawT[maxIdx].ts));
    if(rawT[minIdx]) set('ds-min-h', fmtTs(rawT[minIdx].ts));
    var totalA=rawA.reduce(function(s,p){return s+parseFloat(p.value);},0);
    var totalB=rawB.reduce(function(s,p){return s+parseFloat(p.value);},0);
    var totalC=rawC.reduce(function(s,p){return s+parseFloat(p.value);},0);
    var sum=totalA+totalB+totalC||1;
    var pA=(totalA/sum*100).toFixed(1), pB=(totalB/sum*100).toFixed(1), pC=(totalC/sum*100).toFixed(1);
    var dCanvas=el('dist-canvas');
    if(dCanvas){
      if(CH.dist){CH.dist.destroy();CH.dist=null;}
      CH.dist=new Chart(dCanvas,{
        type:'doughnut',
        data:{labels:[phL(0),phL(1),phL(2)],datasets:[{data:[totalA,totalB,totalC],backgroundColor:['#00EBC8','#00008C','#6366F1'],borderWidth:2,borderColor:'white',hoverBorderWidth:2}]},
        options:{responsive:true,maintainAspectRatio:false,cutout:'65%',
          plugins:{legend:{display:false},tooltip:{callbacks:{label:function(c){return ' '+c.label+': '+((c.raw/sum)*100).toFixed(1)+'%';}}}}}
      });
      if(dCanvas.parentElement) dCanvas.parentElement.style.overflow='visible';
      if(dCanvas.parentElement&&dCanvas.parentElement.parentElement) dCanvas.parentElement.parentElement.style.overflow='visible';
      html('dist-legend',
        '<div class="dist-leg-title">Distribución</div>'+
        [0,1,2].filter(phOn).map(function(i){return '<div class="dl-row"><div class="dl-dot" style="background:'+PH_COL[i]+'"></div><span class="dl-name">'+esc(phL(i))+'</span><strong class="dl-pct">'+[pA,pB,pC][i]+'%</strong></div>';}).join('')
      );
    }
  }

  /* ── FEAT-01 · CURVA DE DEMANDA: 4h · 8h · Hoy · Ayer ──────────────
     Datos propios (DC), independientes de D.demand. Eje X lineal en
     minutos desde la medianoche de Lima (UTC−5 fijo, sin horario de
     verano), sin depender de la zona horaria del navegador.
  ─────────────────────────────────────────────────────────────────── */
  var LIMA_OFFSET=-5*3600000, DAY_MS=86400000, demandTimer=null;
  var DC={view:'hoy', shown:null, req:0, step:120, yday:null, series:'total'};
  var DC_KEYS='potencia_activa_total,potencia_activa_fase_a,potencia_activa_fase_b,potencia_activa_fase_c';
  var DC_SER=['potencia_activa_fase_a','potencia_activa_fase_b','potencia_activa_fase_c','potencia_activa_total'];

  function limaMidnight(offsetDays){
    return Math.floor((nowMs()+LIMA_OFFSET)/DAY_MS)*DAY_MS-LIMA_OFFSET+(offsetDays||0)*DAY_MS;
  }
  function fmtMin(m){ m=((Math.floor(m)%1440)+1440)%1440; return pad(Math.floor(m/60))+':'+pad(m%60); }

  /* Tramo que cruza un hueco (spanGaps): mismo color al 35 % y grosor 1.5 */
  function dcFade(hex){ var n=parseInt(hex.slice(1),16); return 'rgba('+(n>>16)+','+((n>>8)&255)+','+(n&255)+',.35)'; }
  function dcGap(c,v){ return c.p0.skip||c.p1.skip?v:undefined; }
  function dcDs(label,color,width,dash){
    var ds={label:label,data:[],borderColor:color,borderWidth:width,pointRadius:0,fill:false,
      cubicInterpolationMode:'monotone',spanGaps:true,
      segment:{borderColor:function(c){return dcGap(c,dcFade(color));},borderWidth:function(c){return dcGap(c,1.5);}}};
    if(dash) ds.borderDash=dash;
    return ds;
  }

  /* Selector de series (Total · Fases · Todo), recordado por navegador */
  var DC_SKEY='sk360.demandSeriesPem', DC_LEG=['leg-fase-a','leg-fase-b','leg-fase-c','leg-total','leg-total-ayer'];
  function dcSeriesGet(){
    try{ var v=localStorage.getItem(DC_SKEY); return (v==='total'||v==='fases'||v==='todo')?v:'total'; }
    catch(e){ return 'total'; }
  }
  function dcSeriesSet(v){ try{ localStorage.setItem(DC_SKEY,v); }catch(e){} }
  function dcVisibility(){
    var c=CH.demand; if(!c) return;
    var s=DC.series, ph=s!=='total', tot=s!=='fases';
    var vis=[ph&&phOn(0),ph&&phOn(1),ph&&phOn(2),tot,tot&&DC.shown==='hoy'];
    c.data.datasets.forEach(function(ds,i){ ds.hidden=!vis[i]; });
    DC_LEG.forEach(function(id,i){ var e=el(id); if(e) e.style.display=vis[i]?'':'none'; });
  }

  /* Ubica cada punto en su bucket: x = inicio del bucket en minutos desde base. Sin dato → null. */
  function dcSeries(pts,st,end,iv,base){
    var by={};
    (pts||[]).forEach(function(p){
      var v=parseFloat(p.value)/1000; if(isNaN(v)) return;
      by[st+Math.floor((+p.ts-st)/iv)*iv]=v;
    });
    var out=[];
    for(var s=st;s<end;s+=iv) out.push({x:(s-base)/60000,y:by[s]!==undefined?by[s]:null});
    return out;
  }

  function dcRender(view,d,st,end,iv,base,yday,min,max,step){
    var c=CH.demand; if(!c) return;
    d=d||{};
    DC_SER.forEach(function(k,i){ c.data.datasets[i].data=dcSeries(d[k],st,end,iv,base); });
    c.data.datasets[4].data=view==='hoy'?(yday||[]):[];
    var w=(c.chartArea&&c.chartArea.width)||c.width||600;
    var hit=Math.max(3,w*(iv/60000)/(max-min)/2);
    c.data.datasets.forEach(function(ds){ ds.pointHitRadius=hit; });
    c.options.scales.x.min=min; c.options.scales.x.max=max;
    DC.step=step; DC.shown=view;
    dcVisibility();
    c.update('none');
    var sub;
    if(view==='ayer'){ var dt=new Date(base+LIMA_OFFSET); sub='Ayer ('+pad(dt.getUTCDate())+'/'+pad(dt.getUTCMonth()+1)+')'; }
    else sub=view==='hoy'?'Hoy (00:00–24:00)':(view==='4h'?'últimas 4 horas':'últimas 8 horas');
    set('dem-sub','Potencia activa'+(CANALES.length>1?' por canal':'')+' · '+sub);
  }

  function dcLoad(view){
    var id=++DC.req, now=nowMs(), t0=limaMidnight(0), t1=limaMidnight(-1);
    if(view==='4h'||view==='8h'){
      var h=view==='4h'?4:8, st=now-h*3600000, iv=h===4?300000:600000;
      vApi(DC_KEYS,function(k){return tsUrl(k,st,now,iv,'AVG',200);},function(d){
        if(id!==DC.req) return;
        dcRender(view,d,st,now,iv,t0,null,(st-t0)/60000,(now-t0)/60000,h===4?30:60);
      });
    } else if(view==='ayer'){
      vApi(DC_KEYS,function(k){return tsUrl(k,t1,t0,900000,'AVG',200);},function(d){
        if(id!==DC.req) return;
        dcRender('ayer',d,t1,t0,900000,t1,null,0,1440,120);
      });
    } else {
      var end=Math.max(now,t0+60000);
      var today=function(){
        vApi(DC_KEYS,function(k){return tsUrl(k,t0,end,900000,'AVG',200);},function(d){
          if(id!==DC.req) return;
          dcRender('hoy',d,t0,end,900000,t0,DC.yday&&DC.yday.base===t1?DC.yday.data:null,0,1440,120);
        });
      };
      /* "Total ayer" se reutiliza mientras no cambie el día en Lima */
      if(DC.yday&&DC.yday.base===t1){ today(); return; }
      vApi('potencia_activa_total',function(k){return tsUrl(k,t1,t0,900000,'AVG',200);},function(y){
        if(id!==DC.req) return;
        DC.yday={base:t1,data:dcSeries((y||{}).potencia_activa_total,t1,t0,900000,t1)};
        today();
      },function(e){ console.warn('[3EM]',e); if(id===DC.req) today(); });
    }
  }

  function dcInit(){
    var canvas=el('demand-canvas'); if(!canvas||CH.demand) return;
    var gc='rgba(212,224,238,.6)', tk={color:'#96AABF',font:{size:10}};
    CH.demand=new Chart(canvas,{
      type:'line',
      data:{datasets:[
        dcDs(phL(0),'#00EBC8',2),
        dcDs(phL(1),'#00008C',2),
        dcDs(phL(2),'#6366F1',2),
        dcDs('Total','#0D1B2E',2.5,[5,3]),
        dcDs('Total ayer','#94A3B8',1.5)
      ]},
      options:{
        responsive:true,maintainAspectRatio:false,interaction:{intersect:false,mode:'x'},
        plugins:{legend:{display:false},tooltip:{mode:'x',intersect:false,backgroundColor:'white',titleColor:'#5A6E8A',bodyColor:'#0D1B2E',borderColor:'#D4E0EE',borderWidth:1,
          filter:function(i){return i.parsed&&i.parsed.y!==null&&!isNaN(i.parsed.y);},
          callbacks:{
            title:function(items){return items.length?fmtMin(items[0].parsed.x):'';},
            label:function(c){return ' '+c.dataset.label+': '+c.parsed.y.toFixed(2)+' kW';}}}},
        scales:{
          x:{type:'linear',min:0,max:1440,grid:{color:gc,drawBorder:false},
            afterBuildTicks:function(ax){
              var s=DC.step, t=[];
              for(var v=Math.ceil(ax.min/s)*s; v<=ax.max; v+=s) t.push({value:v});
              ax.ticks=t;
            },
            ticks:Object.assign({},tk,{maxRotation:0,callback:function(v){return v===1440?'24:00':fmtMin(v);}})},
          y:{grid:{color:gc,drawBorder:false},ticks:Object.assign({},tk,{callback:function(v){return v.toFixed(1)+' kW';}})}
        }
      }
    });
    document.querySelectorAll('#dem-time-btns .tbtn').forEach(function(btn){
      if(btn._bound) return; btn._bound=true;
      btn.addEventListener('click',function(){
        document.querySelectorAll('#dem-time-btns .tbtn').forEach(function(b){b.classList.remove('active');}); this.classList.add('active');
        DC.view=this.getAttribute('data-v'); dcLoad(DC.view);
      });
    });
    DC.series=CANALES.length<2?'total':dcSeriesGet();   /* A-05: con un solo canal, Total = canal 0 y sin selector */
    document.querySelectorAll('#dem-series-btns .tbtn').forEach(function(btn){
      btn.classList.toggle('active',btn.getAttribute('data-s')===DC.series);
      if(btn._bound) return; btn._bound=true;
      btn.addEventListener('click',function(){
        document.querySelectorAll('#dem-series-btns .tbtn').forEach(function(b){b.classList.remove('active');}); this.classList.add('active');
        DC.series=this.getAttribute('data-s'); dcSeriesSet(DC.series);
        dcVisibility(); if(CH.demand) CH.demand.update('none');
      });
    });
    dcVisibility();
    dcLoad(DC.view);
    if(demandTimer) clearInterval(demandTimer);
    demandTimer=setInterval(function(){ if(DC.view!=='ayer') dcLoad(DC.view); },300000);
  }

  /* ══════════════════════════════════════════════════════════════════
     SECCIÓN 03
  ══════════════════════════════════════════════════════════════════ */
  var PHASE_ROWS=[
    {l:'Voltaje',      u:'V',  a:'voltaje_fase_a',           b:'voltaje_fase_b',           c:'voltaje_fase_c',           volt:true},
    {l:'Corriente',    u:'A',  a:'corriente_fase_a',         b:'corriente_fase_b',         c:'corriente_fase_c'},
    {l:'Pot. Activa',  u:'kW', a:'potencia_activa_fase_a',   b:'potencia_activa_fase_b',   c:'potencia_activa_fase_c',   div:1000},
    {l:'Pot. Aparente',u:'kVA',a:'potencia_aparente_fase_a', b:'potencia_aparente_fase_b', c:'potencia_aparente_fase_c', div:1000},
    {l:'Factor Pot.',  u:'',   a:'factor_potencia_fase_a',   b:'factor_potencia_fase_b',   c:'factor_potencia_fase_c',   fp:true},
    {l:'Energía Acum.',u:'kWh',a:'energia_fase_a',           b:'energia_fase_b',           c:'energia_fase_c',           div:1000},
    {l:'Devuelta',     u:'kWh',a:'energia_ret_fase_a',       b:'energia_ret_fase_b',       c:'energia_ret_fase_c',       div:1000},
  ];
  function renderSec03(){
    var tbody=el('phase-tbody'); if(!tbody) return;
    function fmt(v,row){
      if(v===undefined||v===null||(v===0&&row.fp)) return '—';
      var n=parseFloat(v); if(row.div) n=n/row.div;
      if(row.fp) return fmtFP(n); if(row.div) return n.toFixed(3); return n.toFixed(2);
    }
    tbody.innerHTML=PHASE_ROWS.map(function(r,i){
      var vA=lat(r.a), vB=lat(r.b), vC=lat(r.c), rA='', rB='', rC='';
      if(r.volt&&D.voltMin&&D.voltMax){
        var mkR=function(k){
          var mn=D.voltMin[k],mx=D.voltMax[k]; if(!mn||!mx) return '';
          var mnV=mn[0]?parseFloat(mn[0].value):null, mxV=mx[0]?parseFloat(mx[0].value):null;
          return (mnV&&mxV)?'<div class="pt-range">Rango: '+mnV.toFixed(1)+'–'+mxV.toFixed(1)+' V</div>':'';
        };
        rA=mkR('voltaje_fase_a'); rB=mkR('voltaje_fase_b'); rC=mkR('voltaje_fase_c');
      }
      var bg=i%2===1?'rgba(240,246,252,.6)':'transparent';
      return '<tr style="background:'+bg+'">'+
        '<td><div class="pt-var">'+r.l+'</div>'+(r.u?'<div class="pt-unit">'+r.u+'</div>':'')+'</td>'+
        '<td><div class="pt-val">'+fmt(vA,r)+'</div>'+rA+'</td>'+
        (phOn(1)?'<td><div class="pt-val">'+fmt(vB,r)+'</div>'+rB+'</td>':'')+
        (phOn(2)?'<td><div class="pt-val">'+fmt(vC,r)+'</div>'+rC+'</td>':'')+'</tr>';
