  function renderCostCard(){
    if(D.energyToday===null) return;
    renderCostText();
    var mCanvas=el('monthly-canvas'); if(!mCanvas) return;
    if(CH.monthly){CH.monthly.destroy();CH.monthly=null;}
    var pts=D.monthly.slice(-7), barData=[], barLabels=[];
    var MESES=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
    for(var i=1;i<pts.length;i++){
      var delta=Math.max(0,(pts[i].v-pts[i-1].v)/1000);
      barData.push(Math.round(delta)); barLabels.push(MESES[new Date(pts[i].ts).getMonth()]);
    }
