          '<div><div style="font-size:10px;color:#5A6E8A;margin-bottom:4px">Pico máx. kW</div>'+
            '<input id="cfg-input-kw" type="number" step="1" value="'+KW_MAX+'" style="width:100%;background:#F0F6FC;border:1px solid #D4E0EE;border-radius:8px;padding:6px 10px;font-size:12px;font-weight:600;color:#0D1B2E;font-family:inherit"></div>'+
          '<div><div style="font-size:10px;color:#5A6E8A;margin-bottom:4px">Voltaje mín. V</div>'+
