            '<input id="cfg-input-edisc" type="number" step="0.5" min="1" value="'+EST_DISC_H+'" style="width:100%;background:#F0F6FC;border:1px solid #D4E0EE;border-radius:8px;padding:6px 10px;font-size:12px;font-weight:600;color:#0D1B2E;font-family:inherit"></div>'+
        '</div>'+
