          '<button id="cfg-save-btn" style="background:#00008C;border:none;border-radius:8px;padding:8px 18px;cursor:pointer;font-size:12px;font-weight:700;color:white;font-family:inherit">Guardar cambios</button>'+
          '<span id="cfg-save-fb" style="font-size:11px"></span>'+
        '</div></div>'
      );
    }
    /* Solo Tenant Admin puede editar parámetros */
    var editForm=document.getElementById('cfg-edit-form');
    if(editForm&&(ctx.currentUser&&ctx.currentUser.authority==='CUSTOMER_USER')){
      editForm.style.display='none';
    }
    var saveBtn=el('cfg-save-btn');
    if(saveBtn&&!saveBtn._bound){
      saveBtn._bound=true;
      saveBtn.addEventListener('click',function(){
        // DEV-ONLY (FEAT-01): bloquea escritura en dispositivo de cliente. NO COPIAR A PRODUCCIÓN.
        var devFb=el('cfg-save-fb'); if(devFb) devFb.textContent='Guardado deshabilitado en DEV'; return;
        var fields=[
          {key:'tarifa_kwh',   elId:'cfg-input-tarifa',parse:parseFloat},
          {key:'alerta_fp_min',elId:'cfg-input-fp',    parse:parseFloat},
          {key:'alerta_kw_max',elId:'cfg-input-kw',    parse:parseFloat},
          {key:'voltaje_min',  elId:'cfg-input-vmin',  parse:parseFloat},
          {key:'voltaje_max',  elId:'cfg-input-vmax',  parse:parseFloat},
          {key:'estado_alerta_h',      elId:'cfg-input-ealert', parse:parseFloat},
          {key:'estado_desconexion_h', elId:'cfg-input-edisc',  parse:parseFloat},
        ];
        var payload=[], valid=true;
        fields.forEach(function(f){
          var inp=el(f.elId); if(!inp) return;
          var val=f.parse(inp.value);
          if(isNaN(val)){valid=false;inp.style.borderColor='#EF4444';return;}
          inp.style.borderColor=''; payload.push({key:f.key,value:val});
        });
        if(!valid){alert('Revisa los valores — solo se permiten números');return;}
        var _ea=payload.filter(function(p){return p.key==='estado_alerta_h';})[0], _ed=payload.filter(function(p){return p.key==='estado_desconexion_h';})[0];
        if(_ea&&_ed&&!(_ed.value>_ea.value&&_ea.value>0)){alert('El tiempo de desconexión debe ser mayor que el de alerta');return;}
        ctx.http.post('/api/plugins/telemetry/DEVICE/'+DEVICE_ID+'/SERVER_SCOPE',
          payload.reduce(function(o,p){o[p.key]=p.value;return o;},{})
        ).subscribe(
          function(){
            payload.forEach(function(p){
