  function pemNav(lista){
    var opts=REG.opcionesNav(lista,DASH_ID).map(function(i){return {n:i.etiqueta,d:i.dashboardId};});
    var badge=document.querySelector('.hdr-inst-badge'); if(!badge) return;
    if(opts.length===0){var cr=badge.querySelector('.hdr-caret');if(cr)cr.style.display='none';return;}
    badge.style.position='relative';badge.style.cursor='pointer';badge.style.userSelect='none';
    var dd=document.createElement('div');dd.className='inst-dd';dd.style.display='none';
    var ddHtml='<div class="idd-title">Instalaciones</div>';
    ddHtml+='<div class="idd-current"><span class="idd-check">✓</span>'+esc(INSTALL_NAME)+'<span class="idd-here">Estás aquí</span></div>';
    ddHtml+=opts.map(function(i){
      return '<div class="idd-item" data-d="'+esc(i.d)+'">'+esc(i.n)+'</div>';
    }).join('');
    dd.innerHTML=ddHtml; badge.appendChild(dd);
    badge.addEventListener('click',function(e){
      e.stopPropagation();
      dd.style.display=dd.style.display==='block'?'none':'block';
    });
    dd.querySelectorAll('.idd-item').forEach(function(item){item.addEventListener('click',function(e){e.stopPropagation();window.location.href='/dashboard/'+this.getAttribute('data-d');});});
    document.addEventListener('click',function(){dd.style.display='none';});
  }

